  insert into public.brands (name, website, description, country, status) values ('MyCospara', 'https://mycospara.com', 'French house of Arab perfumery selling vegan, plant-based fragrances inspired by oud, musk and Damascus rose; it runs its own ambassador affiliate program whose page promises commissions with no earning limit and provides marketing tools, personalised support and real-time tracking.', 'France', 'published') returning id into bid;
