  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'MyCospara Affiliate Program (Own Program, Uncapped)', 'https://mycospara.com/en/content/affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mycospara.com/en/content/affiliate-program', 'brand_site', 'affiliate_program', 'MyCospara''s own affiliate program page (fetched) states verbatim that affiliates earn a percentage of every sale through a personalised link ''with no earning limit'', calls the income ''transparent, unlimited'', and says ''The system is simple, with no cap'' - an explicit earnings-cap statement on the brand''s own page, so commission_cap is recorded as uncapped. No percentage rate is published anywhere on the page, so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mycospara.com/en/content/affiliate-program', 'brand_site', 'brand_overview', 'The same brand page (fetched) describes the house as a committed, ethical Arab perfumery brand that rejects synthetic fragrances and celebrates plant-based, vegan ingredients, and publishes the contact email Contact@mycospara.com and a French phone number on the page. No creator count is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 14, 13, 9, 3, '{"compensation": "Verified uncapped earnings on the brand''s own page, but the percentage rate itself is unpublished, which holds the score back.", "contact_access": "A contact email and phone number are published on the brand''s own affiliate page.", "credibility": "A small French fragrance house with a complete, transparent program page but a limited third-party footprint.", "niche_fit": "Fragrance sits inside beauty UGC, though it is a narrower niche than skincare or makeup.", "opportunity_availability": "The program is open to creators, bloggers and enthusiasts through the brand''s own page.", "ugc_evidence": "The program is explicitly pitched at content creators with marketing tools, visuals and personalised strategy support, but no tracked creator campaign data was found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('CeraVe', 'https://www.cerave.com', 'L''Oréal Groupe''s dermatologist-developed drugstore skincare brand, famous for its ceramide cleansers and moisturisers and a phenomenon on SkinTok; creators earn through its official TikTok Shop affiliate program, with terms published on CeraVe''s own domain and joining inside TikTok Shop''s Add Products flow.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'TikTok Shop', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://collabfeed.io/blog/how-cerave-runs-their-creator-program.', 'https://collabfeed.io/blog/how-cerave-runs-their-creator-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'CeraVe TikTok Shop Affiliate Program', 'https://collabfeed.io/blog/how-cerave-runs-their-creator-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://collabfeed.io/blog/how-cerave-runs-their-creator-program', 'creator_platform', 'affiliate_program', 'CollabFeed''s route-verified breakdown (fetched) states CeraVe has no standalone influencer program on cerave.com, that CeraVe publishes official TikTok Shop affiliate terms on its own domain, and that joining happens inside TikTok Shop''s ''Add Products'' flow with no application and commission on sales. It also documents the LOREALISTAR creator club as the application route, with compensation starting as gifting, so the TikTok Shop affiliate is the recorded commission route.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tokconnect.com/guides/tiktok-shop-affiliate-commission-rates/', 'affiliate_directory', 'compensation_data', 'TokConnect''s TikTok Shop listing data (fetched) shows a CeraVe Sheer Tint Mineral Sunscreen SPF 30 listing carrying a 17% open affiliate commission with 937 creators selling it in the measured window. TikTok Shop rates are set per product by the seller, so no single program rate exists and commission_rate is null; 937 creators on one listing is a mid-to-large absolute count, not low, so creator_saturation is unknown. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 19, 10, 5, 10, 5, '{"compensation": "Real commissions exist and one measured listing paid 17%, but rates are per-product and unpublished at program level, so the score stays mid-range.", "contact_access": "There is deliberately no public partnership email; access is self-serve inside TikTok Shop.", "credibility": "A L''Or\u00e9al Groupe flagship with dermatologist positioning and enormous retail distribution.", "niche_fit": "Core SkinTok brand; ceramide routines and derm education are exactly what skincare creators post.", "opportunity_availability": "Open affiliate route with no application - any eligible TikTok Shop creator can add the products today.", "ugc_evidence": "A year of tracked paid placements from nano to celebrity accounts, plus 937 creators selling one measured TikTok Shop listing."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('La Roche-Posay', 'https://www.laroche-posay.com', 'French pharmacy skincare brand built on La Roche-Posay thermal spring water, maker of Effaclar, Anthelios and Cicaplast; it runs an open affiliate program through CJ Affiliate in the US alongside the L''Oréal group creator pipeline.', 'France', 'published') returning id into bid;
