  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'La Roche-Posay Affiliate Program (CJ)', 'https://www.whichprogram.com/en/p/la-roche-posay-affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://collabfeed.io/blog/how-to-reach-brands-with-no-partnership-email', 'creator_platform', 'affiliate_program', 'CollabFeed''s route table (fetched), verified against official brand domains, lists La Roche-Posay''s official route as a CJ affiliate program - an open affiliate - separate from the gifting-first LOREALISTAR creator club.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.whichprogram.com/en/p/la-roche-posay-affiliate-program', 'affiliate_directory', 'affiliate_program', 'WhichProgram''s program listing (fetched) records the La Roche-Posay affiliate program on CJ Affiliate at an 8% base commission per sale with a 30-day cookie, US reach, listed as active from a provider source. Other fetched directories conflict - LinkApprove says up to 7% and Shopper says 5-10% - so commission_rate is recorded as null with the conflict documented. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 18, 9, 5, 8, 5, '{"compensation": "A real network program exists, but published rates conflict between 5% and 10% depending on source, so it cannot be scored as a settled rate.", "contact_access": "No public partnership email exists by design; access runs through the CJ application.", "credibility": "One of the world''s largest dermatologist-recommended pharmacy brands, owned by L''Or\u00e9al.", "niche_fit": "Effaclar, Anthelios and Cicaplast are staple SkinTok products with constant creator demand.", "opportunity_availability": "Open affiliate application through CJ, subject to network approval.", "ugc_evidence": "Tracked paid placements run regularly, including on nano creators, per CollabFeed''s monitoring."}'::jsonb);
