  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://files.constantcontact.com/50fb5b07101/42114b8a-5418-4891-81b2-3a156be85ae9.pdf', 'trade_publication', 'affiliate_program', 'A beauty-industry newsletter (fetched) reports Kenvue''s announcement that Neutrogena''s Collagen Bank line made its retail debut through TikTok Shop, putting the brand''s products into TikTok Shop''s affiliate commerce system where creators earn commission on tagged sales.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.instagram.com/reel/Dc_0pPtml-h/', 'social_post', 'affiliate_program', 'A creator post from September 2026 (fetched) announces Neutrogena''s official arrival on TikTok Shop, stating the brand is offering higher commission rates and free samples to affiliate creators; a second fetched creator post discloses earning commission on Neutrogena purchases made through his TikTok Shop links. Rates are set per product and are not published at program level, so commission_rate is null; no cap statement or creator count is published, so cap and saturation are unknown. An August 2026 CollabFeed check found no public route beyond agency casting, which the later TikTok Shop launch supersedes for the affiliate layer.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 16, 8, 4, 9, 5, '{"compensation": "Commissions are real but undisclosed and set per product, with only launch-period reporting of boosted rates.", "contact_access": "No public partnership contact exists; the brand''s own FAQ warns legitimate outreach never comes from free email accounts, and access is self-serve in TikTok Shop.", "credibility": "A flagship Kenvue brand and one of the most recognised skincare names in US mass retail.", "niche_fit": "Hydro Boost is a perennial creator favourite and the Collagen Bank launch was aimed squarely at TikTok skincare audiences.", "opportunity_availability": "Open through TikTok Shop''s product marketplace to eligible affiliate creators.", "ugc_evidence": "Regular tracked paid placements plus disclosed affiliate hauls after the TikTok Shop debut, though the paid layer remains agency-led."}'::jsonb);
