  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://collabfeed.io/blog/how-to-reach-brands-with-no-partnership-email', 'creator_platform', 'affiliate_program', 'CollabFeed''s route-verified guide (fetched) states that L''Oréal runs open affiliate programs through TikTok Shop in the US and that L''Oréal Paris publishes TikTok Shop terms on its own brand domain; its route table lists ''CeraVe, L''Oréal Paris (US) - TikTok Shop affiliate - Open affiliate, no application''. Rates are set per product inside TikTok Shop and are not published at program level, so commission_rate is null; no cap statement or creator count is published, so cap and saturation are unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 9, 5, 10, 5, '{"compensation": "Open commissions exist but are set per product and unpublished at program level.", "contact_access": "No public partnership email by design; the route in is self-serve through TikTok Shop.", "credibility": "The flagship brand of the world''s largest beauty group.", "niche_fit": "Elvive, Revitalift and True Match give beauty creators proven, high-search-volume products across three categories.", "opportunity_availability": "Open affiliate with no application, per the route-verified source.", "ugc_evidence": "Constant tracked paid creator placements across the L''Or\u00e9al portfolio, with the affiliate layer open to any eligible creator."}'::jsonb);
