  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.influencerrate.com/affiliate-program/naos', 'affiliate_directory', 'affiliate_program', 'InfluencerRate''s NAOS program page (fetched) describes earning commission promoting NAOS skincare brands including Bioderma, but the page dates from 2023 and mixes in unrelated content, so it is recorded as needs_review supporting evidence only; the live, current route evidenced is the brand''s TikTok Shop affiliate recruitment.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 7, 6, 7, 5, '{"compensation": "Commission is promised by the brand itself but no rate is published anywhere fetched.", "contact_access": "The brand answers affiliate requests through its TikTok Shop store, per its own post replies; no public email is published.", "credibility": "A flagship NAOS brand and one of the most recommended pharmacy skincare lines worldwide.", "niche_fit": "Sensibio H2O is an iconic creator product, especially in K-beauty-influenced and pharmacy-skincare content.", "opportunity_availability": "The evidenced recruitment is regional (Malaysia), so availability is narrower than a global open program.", "ugc_evidence": "The brand is actively recruiting creators on its own social accounts, but tracked campaign volume is modest."}'::jsonb);
