  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'rhode Affiliate Program (Impact)', 'https://linkclicky.com/affiliate-program/rhode-skin/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/rhode-skin/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s program listing (fetched) records rhode skin''s affiliate program on the Impact platform at 5% per sale, open to all regions. Skimlinks'' beauty affiliate roundup (fetched) instead describes the rhode program as paying up to 12% - a ceiling figure on a different network - so the published figures conflict and commission_rate is recorded as null with the conflict documented. No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.skimlinks.com/insights/beauty-affiliate-programs/', 'affiliate_directory', 'affiliate_program', 'Skimlinks'' beauty affiliate programs guide (fetched) lists the Rhode skin affiliate program at up to 12% commission, available internationally through Skimlinks, and pitches it to skincare-first editorial and lifestyle creators - corroborating that a commission program exists while conflicting with the 5% Impact figure.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 10, 6, 8, 5, '{"compensation": "Two network listings exist, but the 5% and up-to-12% figures conflict, so compensation is scored on an unsettled rate.", "contact_access": "Access runs through network applications; the brand publishes no creator contact route on its own pages.", "credibility": "A celebrity-founded brand acquired by e.l.f. Beauty, with sustained sell-out demand.", "niche_fit": "Peptide lip and glazing products are among the most-posted skincare items on TikTok and Instagram.", "opportunity_availability": "Open network applications on Impact and access via Skimlinks for publishers.", "ugc_evidence": "Enormous organic creator coverage; the brand''s own creator layer leans gifting, but the affiliate program is a documented commission route."}'::jsonb);
