  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://later.com/blog/how-to-build-a-tiktok-shop-holiday-strategy-that-converts/', 'trade_publication', 'affiliate_program', 'Later''s TikTok Shop strategy guide (fetched) uses Laneige as its worked example, stating that starting in October the brand partnered with affiliates on TikTok Shop to talk about holiday gifting must-haves and promote its holiday bundle - direct evidence of an operating TikTok Shop affiliate route. TikTok Shop rates are set per product and no Laneige program rate is published, so commission_rate is null; a Shopper aggregator page claims 3.2% but is generic boilerplate and is not relied on. No cap statement or creator count is published, so cap and saturation are unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 8, 5, 9, 5, '{"compensation": "Commissions operate per product on TikTok Shop but no rate is published at program level.", "contact_access": "No public creator contact route; access is self-serve inside TikTok Shop.", "credibility": "A flagship Amorepacific brand with global retail distribution through Sephora and beyond.", "niche_fit": "The Lip Sleeping Mask is one of the most viral skincare products on TikTok, squarely in creator territory.", "opportunity_availability": "Open to eligible TikTok Shop affiliate creators in markets where the brand''s shop operates.", "ugc_evidence": "A documented affiliate-driven holiday campaign on TikTok Shop, on top of constant organic creator coverage."}'::jsonb);
