  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Revolution Beauty Affiliate Program (Awin)', 'https://getlasso.co/affiliate/revolution-beauty-us/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/revolution-beauty-us/', 'affiliate_directory', 'affiliate_program', 'Lasso''s Revolution Beauty US program page (fetched) records tiered commissions of 2% and 4% per sale with a 30-day cookie; because the rate is tiered rather than a single published rate, commission_rate is recorded as null with the tiers documented. A UK affiliate-programme directory for beauty bloggers (fetched) lists Revolution Beauty on the Awin network. No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 7, 6, 8, 4, '{"compensation": "Tiered 2% and 4% rates are at the low end for beauty, which caps the score despite the program being well documented.", "contact_access": "Network application only; no public creator email was found on the pages checked.", "credibility": "A listed UK beauty group with global retail presence, though its affiliate rates are modest.", "niche_fit": "Fast-launch, collab-driven makeup is built for creator content and dupe culture.", "opportunity_availability": "Open application through Awin for US-based beauty publishers and creators.", "ugc_evidence": "The brand''s growth model is influencer collaborations, and affiliate roundups consistently list its program for beauty bloggers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lord Tshirt', 'https://lordtshirt.com/', 'Turkish direct-to-consumer graphic T-shirt store (prices in TL, Turkish-language storefront) selling music, anime, film and pop-culture print tees. Its own affiliate page pays a published 10% commission and states there is no limit on earnings, which makes it this round''s one verified-uncapped program. No creator counts are published, so saturation stays unknown.', 'Turkey', 'published') returning id into bid;
