  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lord Tshirt Affiliate Program', 'https://lordtshirt.com/en/pages/collab', 'https://lordtshirt.com/en/pages/collab', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lordtshirt.com/en/pages/collab', 'official_program_page', 'commission_rate', 'Lord Tshirt''s own affiliate page states affiliates ''earn 10% commission on all qualifying purchases'' and, under the heading ''Unlimited Earning Potential'': ''There is no limit to how much you can earn with our affiliate program. The more sales you make, the more commission you earn.'' That explicit no-limit earnings statement on the brand''s own page is why commission_cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lordtshirt.com/en/pages/collab', 'official_program_page', 'creator_program', 'The same page opens the program to ''influencers, bloggers, content creators, website owners'' with monthly payouts via the customer''s preferred method and a private tracking panel. The storefront itself is Turkish (TL pricing, Turkish product copy), which is the basis for the country recorded. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 15, 16, 8, 9, 3, '{"niche_fit": "Graphic tees are everyday creator wardrobe content - haul, styling and print-on-demand design videos all fit, though the catalog is Turkey-focused.", "ugc_evidence": "Own program page explicitly recruits influencers and content creators, with a tracking panel and monthly payouts.", "compensation": "10% commission plus the round''s only verified uncapped statement, published on the brand''s own page.", "contact_access": "Registration is on the brand''s own page; no public affiliate email was verified.", "opportunity_availability": "Open registration, free to join, no upfront investment stated.", "credibility": "Small regional print-on-demand store with a thin public footprint beyond its own storefront; terms verified only on its own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lilysilk', 'https://www.lilysilk.com/', 'Luxury silk and cashmere brand founded in 2010 - apparel, sleepwear, scarves and home essentials in Grade 6A mulberry silk, featured in Vogue, ELLE and Harper''s Bazaar, with US stores in New York. Its US affiliate program runs on Awin with a published tiered commission of 8%-15%; the 8% base tier is recorded. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
