  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'LILYSILK Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/87401', 'https://ui.awin.com/merchant-profile/87401', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/87401', 'affiliate_network', 'commission_rate', 'LILYSILK''s Awin merchant profile (US program) states a ''Competitive tiered commission structure (8%-15%)'' with a 30-day referral cookie and performance bonuses for top affiliates. The 8% base tier is recorded. No earnings-cap statement appears on the profile, so commission_cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/87401', 'affiliate_network', 'creator_program', 'The same profile''s Preferred Publisher Types explicitly include ''Influencer / KOL: Social media influencers and content creators'' alongside content/editorial and community publishers. No creator counts are published, so creator_saturation stays unknown. A brand press release lists pr@lilysilk.com as the media contact, recorded as the PR contact.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 13, 9, 8, 5, '{"niche_fit": "Silk sleepwear, pillowcases and blouses are premium fashion-and-beauty staples - GRWM, sleep-routine and luxury-haul content converts well.", "ugc_evidence": "Awin profile explicitly names influencers/KOLs as a preferred publisher type - a direct creator welcome, not just a publisher program.", "compensation": "8% base tier rising to 15% on a premium basket; rate verified on the network profile itself.", "contact_access": "Join route is via the Awin profile; a published PR email (pr@lilysilk.com) is recorded from the brand''s press release.", "opportunity_availability": "Open Awin program; case-by-case publisher approval applies.", "credibility": "Established global luxury brand founded in 2010 with flagship retail stores; rate verified on Awin itself."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Gaiam', 'https://www.gaiam.com/', 'US yoga and wellness brand founded in 1988 - yoga mats, props, apparel, meditation and active-sitting goods across 1,000+ products. Its affiliate program, running on Rakuten LinkShare since 2001 and now managed through its sister site GetACTV, advertises generous commissions of up to 10% - a ceiling with no published base rate, so the rate is recorded as null. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.gaiam.com/pages/affiliate-program.', 'https://www.gaiam.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Gaiam Affiliate Program (Rakuten)', 'https://www.gaiam.com/pages/affiliate-program', 'https://www.gaiam.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.gaiam.com/pages/affiliate-program', 'official_program_page', 'commission_rate', 'Gaiam''s own affiliate page lists as a program benefit: ''Generous Commissions of up to 10%''. ''Up to 10%'' is a ceiling, not a base rate, so commission_rate is recorded as null rather than guessed. The page also confirms no minimum payout threshold and payments through the LinkShare network. No earnings-cap statement appears, so commission_cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.gaiam.com/pages/affiliate-program', 'official_program_page', 'creator_program', 'The same page confirms the program is free to join, covers 1,000+ products (yoga mats, props, apparel, meditation, active sitting), has run on Rakuten LinkShare since 2001 where it is recognized as a ''Premium Affiliate Program'', and is now applied to via the GetACTV advertiser listing on LinkShare. Directory listings place the brand in the United States (founded in Boulder, Colorado). No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 8, 8, 8, 5, '{"niche_fit": "Yoga is one of the largest creator fitness categories - mat reviews, flow follow-alongs and home-practice setups are evergreen UGC.", "ugc_evidence": "Long-running open affiliate program recruiting promoters for 1,000+ consumer yoga products; classic affiliate structure rather than a creator-named program.", "compensation": "Only an up-to-10% ceiling is published on the brand''s own page, with no base rate to record.", "contact_access": "Join route and program details are on the brand''s own page; no public affiliate email was verified.", "opportunity_availability": "Free to join via Rakuten LinkShare (GetACTV listing); brand approval within ~24 business hours per the page.", "credibility": "Founded 1988, a Rakuten ''Premium Affiliate Program'' since the 2000s with multiple network awards; terms verified on its own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('NOBULL', 'https://www.nobullproject.com/', 'Training footwear and apparel brand built around CrossFit and hard-training culture - minimalist trainers, lifters and graphic training apparel. Its affiliate program is reported on Impact at 10% per sale, and the brand runs its own partnership and sponsorship application route for athletes, creators and coaches. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
