  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'NOBULL Affiliate Program (Impact)', 'https://linkclicky.com/affiliate-program/nobull/', 'https://linkclicky.com/affiliate-program/nobull/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/nobull/', 'affiliate_directory', 'commission_rate', 'LinkClicky''s NOBULL affiliate listing reports the program runs on the Impact platform at 10% per sale, across all regions. The 10% figure is recorded as publicly reported - it was not confirmed on a network profile page. No earnings-cap statement is published, so commission_cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.nobullproject.com/hc/en-us/articles/40798215851415-Partnership-and-Sponsorship-Inquiries-with-NOBULL', 'official_program_page', 'creator_program', 'NOBULL''s own help center maintains a ''Partnership and Sponsorship Inquiries'' route inviting athletes, creators, coaches and NIL athletes to apply, with questions to connect@nobullproject.com - the contact recorded. It notes partnership opportunities are limited and reviewed for brand alignment. No creator counts are published, so creator_saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 14, 11, 7, 5, '{"niche_fit": "NOBULL trainers are default footwear in CrossFit, Hyrox and garage-gym content - shoe rotations and WOD footage are natural UGC.", "ugc_evidence": "Impact affiliate program plus the brand''s own creator/athlete partnership application route on its help center.", "compensation": "10% per sale as reported by the directory listing; not network-profile verified, so scored a step below a verified rate.", "contact_access": "Published partnership email (connect@nobullproject.com) and an application form on the brand''s own help center.", "opportunity_availability": "Affiliate route via Impact; the brand''s own partnership route is application-based and explicitly limited.", "credibility": "Category-defining training brand with a decade of retail presence; program reported consistently across directories."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Berlook', 'https://www.berlook.com/', 'Sustainable women''s swimwear and beachwear brand founded in 2020 and headquartered in Hong Kong/Guangzhou, China, making swimsuits from GRS-certified recycled fabrics including ECONYL regenerated nylon. Its affiliate program runs on ShareASale at a reported 10% per sale, and creator platforms count roughly 391 creators who have posted for the brand. No earnings-cap statement is published, so the cap stays unknown; a few hundred creators is mid-size, so saturation stays unknown rather than low.', 'China', 'published') returning id into bid;
