  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/berlook/', 'affiliate_directory', 'commission_rate', 'LinkClicky''s BERLOOK listing reports the program runs on ShareASale at 10% per sale with a 30-day cookie, open to all regions. The 10% figure is recorded as publicly reported. No earnings-cap statement is published, so commission_cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/berlook', 'affiliate_directory', 'creator_program', 'Beacons'' brand directory counts 391 creators who have posted for Berlook - real creator activity, but a few hundred creators is mid-size in absolute terms, so creator_saturation is recorded as unknown, not low. Brand background (founded 2020, HQ Hong Kong/Guangzhou, recycled-fabric swimwear) is corroborated by the brand''s own site and independent brand reviews.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 14, 8, 8, 4, '{"niche_fit": "Swimwear is peak seasonal UGC - try-on hauls, vacation packing and pool content; the recycled-fabric story gives creators a second angle.", "ugc_evidence": "ShareASale program plus ~391 creators already posting for the brand on creator platforms - proven creator uptake.", "compensation": "10% per sale as reported by the directory listing; not network-profile verified.", "contact_access": "Join route is via ShareASale; no public affiliate email was verified.", "opportunity_availability": "Open ShareASale program; standard network approval applies.", "credibility": "Founded 2020 with consistent independent coverage of its sustainability positioning; younger and smaller than legacy swim brands."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Knockaround', 'https://knockaround.com/', 'San Diego-designed affordable polarized sunglasses brand - durable, colorful shades at accessible prices with a $60 average order value. Its Awin profile advertises up to 15% commission (a ceiling, not a base rate), while a directory listing separately reports a ShareASale program at 10% per sale; with no network-verified base rate, the rate is recorded as null and both figures documented. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
