  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Knockaround Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/50995', 'https://ui.awin.com/merchant-profile/50995', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/50995', 'affiliate_network', 'commission_rate', 'Knockaround''s Awin merchant profile states ''Up to 15% commission on every referred sale'' with a $60 average order value, high repeat purchase rate and a 30-day cookie. ''Up to 15%'' is a ceiling, not a base rate, so commission_rate is recorded as null on the verified network evidence. The profile publishes knockaround@jackalopemediagroup.com for program questions - the contact recorded. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/knockaround/', 'affiliate_directory', 'commission_rate', 'LinkClicky separately lists Knockaround on ShareASale at 10% per sale with a 30-day cookie. That directory figure is documented here as publicly reported rather than recorded over the null, because it could not be confirmed on a network profile. No creator counts are published on either source, so creator_saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 8, 12, 8, 5, '{"niche_fit": "Affordable polarized shades are easy creator content - running, festival, beach and everyday-carry roundups; $60 baskets keep conversion realistic.", "ugc_evidence": "Open Awin program actively pitched to affiliates with marketing assets and support; a second network route is also reported.", "compensation": "Only an up-to-15% ceiling is network-published and the 10% figure is directory-reported, so compensation scores low despite the healthy AOV.", "contact_access": "A program contact email (knockaround@jackalopemediagroup.com) is published on the Awin profile itself.", "opportunity_availability": "Open Awin program for the US market; standard network approval applies.", "credibility": "Long-running San Diego eyewear brand with national retail presence; program verified on Awin itself."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Shady Rays', 'https://www.shadyrays.com/', 'Louisville, Kentucky-founded polarized sunglasses brand (2012) built on its Lost & Broken replacement guarantee, shipping from its Simpsonville, KY headquarters. It runs a named Content Creator Program on Refersion whose published terms describe performance-based commissions on net sales for approved creators - but rates are communicated only on acceptance and treated as confidential, so the rate is recorded as null. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
