  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://n086p8.refersion.com/', 'official_program_page', 'creator_program', 'Shady Rays'' Refersion portal publishes the ''Shady Rays Content Creator Program'' terms (effective 03/26/2026): a performance-based affiliate program in which approved participants (''Creators'') promote Shady Rays products through digital content and earn commission on qualifying sales via unique affiliate links or codes, calculated monthly on net sales.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://n086p8.refersion.com/', 'official_program_page', 'commission_rate', 'The same published terms state ''Commission rates will be communicated upon acceptance and may vary based on performance tiers'' and bar creators from disclosing commission rates - so no published rate exists and commission_rate is recorded as null rather than guessed. No earnings-cap statement appears in the terms, so commission_cap is unknown, and no creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 7, 8, 7, 5, '{"niche_fit": "Adventure-lifestyle sunglasses with a lost-and-broken replacement story - strong outdoor, fishing, running and lake-life content fit.", "ugc_evidence": "A dedicated, named Content Creator Program with published terms written for creators specifically - the clearest creator-first structure in this round.", "compensation": "Rates are deliberately unpublished and confidential until acceptance, so compensation cannot be scored on evidence.", "contact_access": "Application runs through the brand''s Refersion portal; no public affiliate email was verified.", "opportunity_availability": "Approval-based creator program; participation is subject to brand approval per the published terms.", "credibility": "Founded 2012, independently owned, national retail stores and a 75,000-sq-ft Kentucky HQ; terms verified on the brand''s own portal."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Diamondback Fitness', 'https://www.diamondbackfitness.com/', 'US home-fitness equipment brand selling upright and recumbent bikes, ellipticals and indoor cycles factory-direct. Its own affiliate page offers up to 10% commission on qualified purchases through a program run exclusively on AvantLink - a ceiling with no published base rate, so the rate is recorded as null. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
