  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Diamondback Fitness Affiliate Program (AvantLink)', 'https://www.diamondbackfitness.com/pages/affiliates', 'https://www.diamondbackfitness.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.diamondbackfitness.com/pages/affiliates', 'official_program_page', 'commission_rate', 'Diamondback Fitness''s own affiliate page states: ''When a customer you have referred makes any purchase on our factory-direct site, you make a great commission! - Earn up to 10% for every qualified purchase.'' ''Up to 10%'' is a ceiling with no published base rate, so commission_rate is recorded as null. No earnings-cap statement appears, so commission_cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.diamondbackfitness.com/pages/affiliates', 'official_program_page', 'creator_program', 'The same page states the program is offered ''exclusively in the Avantlink affiliate network'' and approval runs through AvantLink, with banners and text links provided. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 8, 8, 8, 4, '{"niche_fit": "Home cardio equipment is steady home-gym content - setup, review and workout-follow-along formats; big-ticket items mean fewer but larger sales.", "ugc_evidence": "Own affiliate page recruiting referrals with network-provided creative; no dedicated creator program was verified beyond the AvantLink route.", "compensation": "Only an up-to-10% ceiling is published on the brand''s own page, with no base rate to record.", "contact_access": "Join route is via the brand''s affiliate page into AvantLink; no public affiliate email was verified.", "opportunity_availability": "Open AvantLink program; standard network approval applies.", "credibility": "Long-running US fitness-equipment brand selling factory-direct; terms verified on its own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Trainline', 'https://www.thetrainline.com/', 'London-headquartered rail and coach booking platform selling train tickets for 270+ operators across 45 countries, with an average European booking around EUR 80. Its affiliate program, run through Travelpayouts, pays a published 3% of the booking cost for new clients and 1% for existing clients on a 30-day cookie; the 3% new-client rate is recorded. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Travelpayouts', 3, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.travelpayouts.com/blog/earn-with-trainline/.', 'https://www.travelpayouts.com/blog/earn-with-trainline/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Trainline Affiliate Program (Travelpayouts)', 'https://www.travelpayouts.com/blog/earn-with-trainline/', 'https://www.travelpayouts.com/blog/earn-with-trainline/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/earn-with-trainline/', 'affiliate_network', 'commission_rate', 'Travelpayouts'' Trainline program page states: ''Join the Trainline affiliate program and get 3% of the booking cost for new clients and 1% for existing clients,'' with a 30-day cookie and an average check of ~EUR 80 in Europe and ~GBP 50 in the UK. The 3% new-client rate is recorded, with the 1% returning-client rate documented here. No earnings-cap statement appears, so commission_cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/earn-with-trainline/', 'affiliate_network', 'creator_program', 'The same network page runs open enrollment for the Trainline program through Travelpayouts, aimed at travel publishers and creators monetizing European rail content. Trainline is headquartered in London and sells tickets for 270+ rail and coach companies. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 8, 9, 9, 5, '{"niche_fit": "European rail is a core travel-creator topic - itinerary, Eurail-vs-point-to-point and budget-Europe content all link naturally to ticket booking.", "ugc_evidence": "Open network enrollment with creator-facing tools (deep links, widgets, banners) via Travelpayouts; no brand-run creator page was verified.", "compensation": "3% on new-client bookings (1% returning) is thin per sale, partly offset by ~EUR 80 average bookings and high conversion intent.", "contact_access": "Join and support route runs through the Travelpayouts program page and dashboard.", "opportunity_availability": "Open enrollment through the network; among the easiest travel programs to start with.", "credibility": "Europe''s leading rail retail platform, founded 1997 and London-headquartered; terms verified on the network''s own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FlixBus', 'https://www.flixbus.com/', 'Munich-founded intercity bus network (Flix) running affordable coach routes across Europe and the US. Its affiliate program through Travelpayouts pays a published 5% of the order cost on US bookings (average order $34.92); separate network listings show different figures, documented in the evidence. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'Germany', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Travelpayouts', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.travelpayouts.com/blog/flixbus-affiliate-program/.', 'https://www.travelpayouts.com/blog/flixbus-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FlixBus Affiliate Program (Travelpayouts)', 'https://www.travelpayouts.com/blog/flixbus-affiliate-program/', 'https://www.travelpayouts.com/blog/flixbus-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/flixbus-affiliate-program/', 'affiliate_network', 'commission_rate', 'Travelpayouts'' FlixBus program page states: ''Commission for FlixBus affiliates is 5% of the order cost'' for the FlixBus US affiliate program, with a $34.92 average order price and a customer-lifetime-value attribution model. The 5% Travelpayouts rate is recorded. Other listings differ by network - an Awin US data table shows 6% and a directory shows a $6 flat figure - documented here as separate network listings rather than a conflict on the recorded route. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/flixbus-affiliate-program/', 'affiliate_network', 'creator_program', 'The same network page offers open enrollment in the FlixBus program through the Travelpayouts dashboard, with link builder, links and poster tools for travel publishers and creators. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 10, 8, 9, 5, '{"niche_fit": "Budget intercity bus travel is a staple of backpacker and budget-Europe content; low fares make it an easy recommendation in itinerary videos.", "ugc_evidence": "Open network enrollment with creator tooling via Travelpayouts; no brand-run creator program was verified.", "compensation": "5% of the order cost on the recorded network route; low average order (~$35) caps per-sale earnings despite the fair percentage.", "contact_access": "Join and support route runs through the Travelpayouts program page and dashboard.", "opportunity_availability": "Open enrollment through the network for the US program.", "credibility": "Europe''s dominant intercity bus brand, Munich-founded and operating globally; terms verified on the network''s own page."}'::jsonb);
