  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'USA Medical affiliate program - 30% commission, no earnings limit stated in the program FAQ on the brand''s own page', 'https://usamedical.com/en/affiliate/', 'https://usamedical.com/en/affiliate/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usamedical.com/en/affiliate/', 'brand_site', 'affiliate_program', 'USA Medical''s own affiliate page offers creators 30% of every sale made through their unique link or coupon, a 30-day cookie, monthly payouts via PayPal, a free bottle of CBG Oil and custom banners/coupons. The program is aimed at influencers, bloggers and YouTubers and requires a minimum of 1,000 followers.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usamedical.com/en/affiliate/', 'brand_site', 'commission_cap', 'The program FAQ''s ''How Much Commission Can I Earn?'' answer states verbatim: ''The more you share your special link and the more people buy through it, the more money you can make. There''s no limit!'' - an explicit no-limit statement about earnings on the brand''s own page, so the cap is verified uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usamedical.com/en/affiliate/', 'brand_site', 'commission_rate', 'One section of the same page (linking from Facebook/Instagram) mentions ''40%'' once, against 30% stated repeatedly throughout the rest of the page; the dominant published figure of 30% is recorded and the stray mention is documented here.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 15, 19, 8, 7, 3, '{"niche_fit": "CBG/hemp oil sits in the wellness niche with routine-based content angles, though it is a single-product line.", "ugc_evidence": "The program page is written directly for influencers, bloggers and YouTubers, with free product, custom coupons and banners and a link-in-bio requirement.", "compensation": "A 30% commission plus an explicit ''There''s no limit!'' answer to the earnings question on the brand''s own FAQ - the cap is verified uncapped.", "contact_access": "No email is published on the program page; contact is through the join form only.", "opportunity_availability": "Open application with near-instant approval, but a 1,000-follower minimum narrows eligibility.", "credibility": "A small, little-known hemp brand with basic program copy; far less established than the large CBD names."}'::jsonb);
