  insert into public.brands (name, website, description, country, status) values ('Cidero & Co.', 'https://cidero.net', 'Premium enrichment products designed specifically for indoor cats — interactive aquarium lamps, motion-activated fish and gecko toys, kickers and tunnels — sold direct from its own store since 2023, with 10k+ units sold. Its affiliate page invites cat influencers to earn a flat 20% commission per sale and states plainly that affiliates earn on every referred sale with no caps.', 'United States', 'published') returning id into bid;
