  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'UpPromote', 20, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://cidero.net/pages/affiliates-partner-with-cidero-co.', 'https://cidero.net/pages/affiliates-partner-with-cidero-co', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cidero & Co. Affiliate Program — brand''s own page publishes 20% per sale ''with no caps'' for cat creators', 'https://cidero.net/pages/affiliates-partner-with-cidero-co', 'https://cidero.net/pages/affiliates-partner-with-cidero-co', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cidero.net/pages/affiliates-partner-with-cidero-co', 'official_site', 'affiliate', 'Cidero & Co.''s own affiliate page fetched in full: ''20% Commission Per Sale'', ''30-Day Cookie'', ''PayPal Payouts'', ''10k+ Units Sold'', and under 20% Commission: ''One of the most generous payouts in the cat niche. Earn on every referred sale with no caps.'' The explicit no-caps earnings statement sits on the brand''s own page, so commission_cap is recorded as uncapped. Applications run through a partner portal on UpPromote (the page''s Join button links to af.uppromote.com) and are reviewed within 48 hours; affiliates get a personal link plus a custom discount code. The page is aimed squarely at cat creators on Instagram, TikTok, YouTube and blogs. No creator count is published, so saturation stays unknown. Country is recorded as the brand''s primary market (USD storefront); the brand sells globally and does not publish an HQ address on the fetched pages.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 18, 11, 9, 4, '{"niche_fit": "A single-species, single-setting niche (indoor cats) is exactly the kind of focused audience UGC creators build channels around.", "ugc_evidence": "The program page is written for cat influencers and names Instagram, TikTok, YouTube and blogs as the intended channels, with complimentary products for top ambassadors.", "compensation": "20% per sale is at the top of the pet-products range, it is verified uncapped on the brand''s own page, and payouts are by PayPal with no stated minimum.", "contact_access": "Open application on the brand''s own page with a stated 48-hour review; no published email, so access runs through the portal only.", "opportunity_availability": "Program is live and recruiting now, with applications reviewed within 48 hours and links issued on approval.", "credibility": "Operating since 2023 with 10k+ units sold claimed on its own page; a young, small brand, so a point is held back versus established names."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('LibertyPaw', 'https://libertypaw.com', 'Family-owned retailer of American-made pet products — toys, gear, grooming tools, beds and supplements, all made in the USA — run from St. Petersburg, Florida. Its Brand Ambassador Program is built specifically for pet Instagram and TikTok creators and pays 10% commission on most products (5% on K9 dryers, dog beds and crate pads) through UpPromote, with a 30-day cookie.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'ambassador@libertypaw.com', 'https://libertypaw.com/pages/affiliate', 'https://libertypaw.com/pages/affiliate', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'UpPromote', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://libertypaw.com/pages/affiliate.', 'https://libertypaw.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'LibertyPaw Brand Ambassador Program — 10% commission for pet Instagram/TikTok creators, tracked via UpPromote', 'https://libertypaw.com/pages/affiliate', 'https://libertypaw.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://libertypaw.com/pages/affiliate', 'official_site', 'affiliate', 'LibertyPaw''s own affiliate page fetched in full, including its Program Rules (last updated November 6, 2026): sign-up, tracking and payouts are handled through UpPromote; commission is 10% on eligible products and 5% on K-9 dryers, dog beds and crate pads, calculated after discounts; links track purchases within 30 days; commissions are paid by PayPal or check after a 35-day holding period. Eligibility is creator-specific: a real, active pet account on Instagram or TikTok with at least 2,500 genuine followers, posting at least 3 times a week, 18+, US-based. The page publishes ambassador@libertypaw.com and shop@libertypaw.com and the company address in St. Petersburg, FL. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 13, 14, 7, 4, '{"niche_fit": "Made-in-USA pet gear is a clear, filmable angle for pet creators, and the catalog (toys, gear, grooming, supplements) suits everyday pet content.", "ugc_evidence": "The program is explicitly built for pet Instagram accounts and TikTok creators, with follower and posting-frequency requirements written into its rules.", "compensation": "10% on most products is mid-range for pet retail; the 5% tier on dryers, beds and crate pads and the 35-day hold keep it below the top scorers.", "contact_access": "Two published emails (ambassador@ and shop@), a phone number and a street address on the program page \u2014 well above the norm.", "opportunity_availability": "Open now but gated: 2,500+ genuine followers, 3 posts a week and US residency are hard requirements, which narrows who can take it up.", "credibility": "Family-owned, publishes its address, rules and a 30-Day Happiness Guarantee; a small brand, so not full marks."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Pawganix', 'https://pawganix.com', 'Pet supplement brand built around the gut-skin connection: YeastGuard and MoveGuard daily chews for dogs and the CalmGuard pheromone calming kit for cats. Its Pawganix Pro creator program pays 20% of a new customer''s first order and 10% of that customer''s reorders and subscription renewals for 12 months, with a 90-day click window, free product to film and no follower minimum.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://pawganix.com/pages/creator-partners', 'https://pawganix.com/pages/creator-partners', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://pawganix.com/pages/creator-partners.', 'https://pawganix.com/pages/creator-partners', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pawganix Pro for Creators — 20% on first orders plus a 10% reorder tail for 12 months, no follower minimum', 'https://pawganix.com/pages/creator-partners', 'https://pawganix.com/pages/creator-partners', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pawganix.com/pages/creator-partners', 'official_site', 'affiliate', 'Pawganix''s own Pawganix Pro creator page fetched in full: ''20% of a new customer''s first order through your link, then 10% of their reorders and subscription renewals for 12 months. Free product to film, and every click is credited to you for 90 days.'' No follower minimum, no content quotas, no contract or exclusivity; applications are read by a person and answered within two working days; pay is monthly by PayPal or bank transfer with an itemised statement. The recorded 20% is the first-order rate; the 10% reorder rate and 12-month tail are documented here rather than blended. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown. Country is recorded from the brand''s own British-English programme pages; the storefront prices in USD and sells internationally.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 16, 9, 9, 3, '{"niche_fit": "Problem-led pet supplements (itchy yeasty dogs, joint support, cat calming) are natural before/after UGC material for dog and cat creators.", "ugc_evidence": "A dedicated creator programme with free product to film, no scripts or quotas, and named creator support \u2014 built for UGC rather than adapted from a publisher program.", "compensation": "20% on first orders plus 10% on reorders for a full year is a strong structure; held below the top band because the reorder rate halves and no cap statement is published.", "contact_access": "Application form on the brand''s own page with a named human reviewer and a two-working-day reply promise; no published email.", "opportunity_availability": "Open to dog and cat creators of any size right now, with product shipped on approval \u2014 nothing about it is invite-only.", "credibility": "A young, small brand with a few hundred published reviews (4.88 average from 291 on its own groomer page); supplement claims are carefully hedged on its pages, but the track record is short."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Clear Drop', 'https://www.onecleardrop.com', 'Maker of home pre-recycling appliances: the Soft Plastic Compactor (SPC), which presses soft plastics into dense recyclable blocks against a $200 deposit, and the Organics Collector (OC), an odor-neutralizing food-waste collector. Its affiliate program runs on Awin at a standard 15% commission and expressly welcomes content creators, influencers, communities and UGC partners.', 'United States', 'published') returning id into bid;
