  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'marketing@onecleardrop.com', 'https://ui.awin.com/advertiser-terms/122058/brand', 'https://ui.awin.com/advertiser-terms/122058/brand', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/advertiser-terms/122058/brand.', 'https://ui.awin.com/advertiser-terms/122058/brand', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Clear Drop Affiliate Program on Awin — 15% standard commission on home pre-recycling appliances, creators expressly allowed', 'https://ui.awin.com/advertiser-terms/122058/brand', 'https://ui.awin.com/advertiser-terms/122058/brand', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/advertiser-terms/122058/brand', 'official_site', 'affiliate', 'Clear Drop''s official Awin program terms fetched in full (last updated 09 Dec 2025): ''Standard commission rate is 15%. It applies on $200 SPC deposit, full price for OC. It doesn''t apply on consumables (filters, mailers).'' Commissions are approved after a 30-day return period and paid via Awin. The terms'' allowed partner types expressly include ''Content creators and influencers'', ''Communities and UGC'' and ''Social traffic''. The same page publishes the affiliate contact marketing@onecleardrop.com. No earnings-cap statement and no creator count appear in the terms, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 16, 12, 8, 4, '{"niche_fit": "A first-of-its-kind home appliance with a visible, satisfying transformation (loose soft plastic in, dense block out) is strong demo content for home and sustainability creators.", "ugc_evidence": "The Awin terms expressly allow content creators, influencers, communities and UGC partner types \u2014 creator eligibility is documented, though the program is network-run rather than creator-branded.", "compensation": "15% is a healthy rate for a home appliance, and it applies to the full OC price and the SPC deposit; consumables are excluded, which trims repeat-purchase earnings.", "contact_access": "A published affiliate contact email (marketing@onecleardrop.com) inside the official program terms, plus Awin''s standard publisher route.", "opportunity_availability": "Live on Awin and open to applications now, subject to brand approval as the terms state.", "credibility": "Registered trademarks, detailed published terms and branding rules suggest an organised operator; still a young niche brand, so a point is held back."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cat Person', 'https://www.catperson.com', 'Cat-only brand selling high-protein wet and dry food plus designed essentials (convertible beds, bowls and gear) for cats and the people who live with them, on one-time purchase or subscription. Its affiliate program runs on Impact and pays 12–15% on one-time purchases, with subscription trials paying $8 plus 15%, on a 30-day cookie.', 'United States', 'published') returning id into bid;
