  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cat Person Affiliate Program on Impact — 12–15% on one-time sales, $8 + 15% on subscription trials', 'https://linkclicky.com/affiliate-program/cat-person/', 'https://linkclicky.com/affiliate-program/cat-person/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/cat-person/', 'directory', 'affiliate', 'LinkClicky''s Cat Person listing (fetched) records: ''Commission: 12%-15% per one-time sale, $8, 15% per subscription trial'' on the Impact platform. Meer''s World''s pet-program roundup independently reports the same structure — 12% to 15% for one-time purchases, $8.00/15% for subscription trials, 30-day cookie, powered by Impact Radius, US service area. Because the published rate is a range, the recorded 12 is its floor, with the full structure documented here. Neither source publishes an earnings-cap statement or a creator count, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 15, 8, 8, 4, '{"niche_fit": "A cats-only food and essentials brand maps perfectly onto cat-creator audiences, an underserved segment next to dog brands.", "ugc_evidence": "An established Impact program with a subscription-trial bounty structure that rewards creator-driven first orders; the evidence is directory-level rather than a creator-branded page.", "compensation": "12\u201315% on food plus $8/15% on trials is solid for consumables with subscription repeat potential; recorded at the 12% floor.", "contact_access": "Application runs through Impact and directory listings; no published partnerships email was found on a fetched page.", "opportunity_availability": "Listed as an active Impact program with a 30-day cookie; US service area only.", "credibility": "An established DTC pet brand with consistent reporting across two independent directories; nothing negative surfaced."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('KeySmart', 'https://www.getkeysmart.com', 'Compact key organizers and everyday-carry accessories — the original KeySmart key holder, tile-compatible trackers, multi-tools and carry gear — sold direct from getkeysmart.com. Its affiliate program pays 10% per sale; the published cookie window is a short 5 days, and the network behind the program is not publicly named in the sources fetched.', 'United States', 'published') returning id into bid;
