  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/keysmart/', 'directory', 'affiliate', 'Lasso''s KeySmart program page fetched in full: ''Commission Rate: 10% Per Sale'', ''Cookie Duration: 5 Days'', and its FAQ repeats ''The commission rate for KeySmart affiliates is 10% Per Sale... This rate applies to all products.'' The listing links sign-up to the brand''s own site (getkeysmart.com) but does not name an affiliate network, so network is recorded as unknown — verify at application, following the directory precedent for unpublished networks. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 13, 7, 8, 4, '{"niche_fit": "Key organizers and pocket gear are proven EDC and gift content; the brand is a category originator, which helps creators tell the story.", "ugc_evidence": "A standing affiliate program paying on all products, evidenced at directory level; no creator-specific program page was found on the brand''s own site.", "compensation": "10% per sale is fair for accessories, but the 5-day cookie is the shortest in this batch and will cost creators conversions.", "contact_access": "Sign-up routes through the brand''s site via the directory listing; no published partnerships email and the network is unnamed, so access is murkier than peers.", "opportunity_availability": "Program is listed as active with applications open; approval is by the brand''s review.", "credibility": "A long-running, widely retailed EDC brand; the thin public program documentation keeps it below full marks."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ecobee', 'https://www.ecobee.com', 'Canadian smart-home brand behind the ecobee Smart Thermostat, SmartSensors, smart cameras and doorbells, and the Smart Security subscription. Its consumer affiliate program pays 6% per sale through Rakuten Advertising. (Its separate ecobee Air Filters for Pro scheme is a contractor trade program and is not the route recorded here.)', 'Canada', 'published') returning id into bid;
