  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ecobee Affiliate Program via Rakuten — 6% per sale on smart thermostats, cameras and security', 'https://getlasso.co/affiliate/ecobee/', 'https://getlasso.co/affiliate/ecobee/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/ecobee/', 'directory', 'affiliate', 'Lasso''s ecobee program page fetched: ''Commission Rate: 6% Per Sale'', categories Home Security and Tech. A smart-home affiliate guide fetched the same week states ''Lasso''s directory lists ecobee at 6% through Rakuten'', naming Rakuten Advertising as the network; a second guide''s 6–8% range brackets the same figure, so 6 is recorded as the published base. Ecobee''s own support site documents a separate Air Filters for Pro contractor scheme on Refersion (10% of lifetime revenues) — that is a trade/professional program and is expressly NOT the qualifying route; the consumer Rakuten program is. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 10, 7, 8, 5, '{"niche_fit": "Smart thermostats and home security are core smart-home creator territory, and ecobee is one of the two names every buyer compares \u2014 high content demand.", "ugc_evidence": "A standing consumer affiliate program on a major network that tech and smart-home bloggers actively promote; not creator-branded, so mid-band.", "compensation": "6% is low in percentage terms, though ticket prices on thermostats and camera bundles soften that; no cap statement is published.", "contact_access": "Application via Rakuten and directory listings; no published partnerships email found on a fetched page.", "opportunity_availability": "Program is listed as active and open to apply through the network now.", "credibility": "A major, long-established smart-home brand owned by Generac, with products in mass retail \u2014 as checkable as brands get."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Redbarn', 'https://www.redbarn.com', 'US pet brand, founded in 1996, making premium dog and cat food, treats, bully sticks, chews and filled bones. Its affiliate program runs on Impact: the brand''s own affiliate page publishes 5% commission on new-customer sales and 3% on existing-customer sales, a 30-day cookie, and a free Gut Health trial pack for new affiliates.', 'United States', 'published') returning id into bid;
