  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Redbarn Affiliate Program on Impact — 5% on new-customer sales (3% returning), 30-day cookie, free trial pack', 'https://www.redbarn.com/pages/affiliate', 'https://www.redbarn.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.redbarn.com/pages/affiliate', 'official_site', 'affiliate', 'Redbarn''s own affiliate page (fetched via the brand''s site): ''We will offer you: Free Gut Health Trial Size Variety Pack, 5% commission, 30-day cookie tracking time'' and ''You earn a 5% commission on new customer sales and 3% commission on existing customer sales'', with tracking links issued ''within the Impact platform''. LinkClicky''s listing corroborates Impact with a $10 / 3%–5% structure. The recorded 5 is the published new-customer rate; the 3% returning-customer rate is documented here. (An older 2022 terms page on the brand''s site describes a different 7%-of-profit structure and is treated as superseded by the current program page.) No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 9, 8, 8, 5, '{"niche_fit": "Natural treats, chews and food for dogs and cats are everyday pet-creator content with strong repeat purchase behaviour.", "ugc_evidence": "The brand''s program page addresses bloggers, influencers and freelancers and sweetens joining with free product; evidence is the brand''s own page plus directory corroboration.", "compensation": "5% new / 3% returning is the lowest rate structure in this batch \u2014 the score reflects that honestly despite the free trial pack.", "contact_access": "Program page and Impact application route are public; no published partnerships email was found on the fetched page.", "opportunity_availability": "Live on Impact with applications open now and a 30-day cookie.", "credibility": "Founded in 1996, widely distributed in US pet retail, with consistent program reporting across its own page and directories."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('GreenPan', 'https://www.greenpan.com', 'Cookware brand that pioneered ceramic nonstick: Thermolon-coated frypans, cookware sets, bakeware and small electrics, marketed on PFAS-free, non-toxic cooking. Its affiliate program runs on CJ Affiliate at 5% per sale with a 30-day cookie.', 'United States', 'published') returning id into bid;
