  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/greenpan/', 'directory', 'affiliate', 'Lasso''s GreenPan program page and its cooking-programs roundup (both fetched) agree: ''Commission Rate: 5% Per Sale'', ''Cookie Duration: 30 Days'', ''Affiliate Network: Commission Junction'' (CJ Affiliate), $50 payout threshold. Shopper''s partnership listing gives a 5–10% payout range, which brackets the 5% base rather than contradicting it, so 5 is recorded. No earnings-cap statement and no creator count are published in any fetched source, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 9, 7, 8, 5, '{"niche_fit": "Non-toxic cookware is a staple of home and kitchen creator content, and GreenPan is the category''s best-known name \u2014 reliable search and gift-guide demand.", "ugc_evidence": "A long-standing CJ program promoted by cooking bloggers; directory-level evidence, not a creator-branded page, so mid-band.", "compensation": "5% is low, partly offset by cookware basket sizes; a directory range up to 10% suggests headroom for negotiated rates but nothing higher is published as base.", "contact_access": "Application through CJ and directory listings; no published partnerships email found on a fetched page.", "opportunity_availability": "Listed as active on CJ with applications open now.", "credibility": "The originator of ceramic nonstick, sold in major retailers internationally for nearly two decades \u2014 fully checkable."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('CATLINK', 'https://www.catlink.com', 'Pet-tech brand specialising in self-cleaning automatic litter boxes (Scooper series) with app control and cat health monitoring, plus ramps and accessories for multi-cat and mobility-limited cats. Its affiliate program pays up to 5.25% per sale on a 14-day cookie; because the only published figure is a ceiling, no base rate is recorded.', 'China', 'published') returning id into bid;
