  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/catlink/', 'directory', 'affiliate', 'Lasso''s CATLINK program page fetched in full: ''Commission Rate: Up to 5.25%'', ''Cookie Duration: 14 days'', category Pets, and its FAQ repeats ''The commission rate for CATLINK affiliates is Up to 5.25%... This rate applies to all products.'' An ''up to'' figure is a rate ceiling, not a base rate, so commission_rate is recorded as null with the ceiling documented here (the Hyperice precedent). The listing does not name the underlying affiliate network, so network is recorded as unknown — verify at application. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 8, 7, 8, 4, '{"niche_fit": "Self-cleaning litter boxes are high-ticket, highly demonstrable pet tech \u2014 unboxings, app walkthroughs and multi-cat tests are proven cat-creator formats.", "ugc_evidence": "A standing affiliate program in the pets category at directory level; no creator-branded program page was found on the brand''s own site.", "compensation": "Only a ceiling (up to 5.25%) is published and the 14-day cookie is short; high unit prices are the offset, but with no published base rate this scores low.", "contact_access": "Directory listing only; no published partnerships email and the network is unnamed in the fetched source.", "opportunity_availability": "Listed as active with no approval requirements stated in the directory; applications open now.", "credibility": "An established pet-tech brand with broad retail and marketplace presence; thinner public program documentation than the batch''s leaders."}'::jsonb);
